    Object.keys(B.pr).forEach(id => { const o = pm[id] = pm[id] || { id: id, nombre: nom[id] || id, cantA: 0, impA: 0, utilA: cu ? 0 : null }; o.cantB = dr2(B.pr[id][0]); o.impB = dr2(B.pr[id][1]); o.utilB = cu ? dr2(B.pr[id][2]) : null; });
