      LS.del(ctoDraftKey(S.cto.id)); cerrarModal(); S.cto = d; S.ctoFiltro = 'dif'; toast(firma ? '✔ Conteo cerrado y enviado al dueño para aplicar los ajustes' : '✔ Conteo cerrado'); pintarConteo();
