    bind('#lpCat', 'cat'); bind('#lpTxt', 'txt'); bind('#lpGrupo', 'grupo'); bind('#lpIva', 'iva', 1); bind('#lpExist', 'exist', 1); bind('#lpSolo', 'solo', 1);
    $('#lpLab').onchange = () => { f.lab = $('#lpLab').value; V.precios(); };
