    document.querySelectorAll('[data-marcar]').forEach(x => x.onclick = () => { if (x.dataset.marcar === '1') lpFiltrados().forEach(p => f.marc[p.id] = 1); else { f.marc = {}; f.solo = false; $('#lpSolo').checked = false; } pintarPrecios(); });
