    $('#pfMarcar').onclick = () => { (S.portTarj || []).slice(0, 300).forEach(t => t.miembros.forEach(p => C.ids[p.id] = true)); cuenta(); pintar(); };
    enlazarFiltros(pintar); enlazarFiltro('#pfFicha', pintar); enlazarFiltro('#pfElegidos', pintar); cuenta(); pintar();
