      const s = une(2, c0, nc); s.value = 'Interés Veterinario®' + ((h.sub || [])[0] ? '  ·  ' + h.sub[0] : ''); s.font = { name: 'Calibri', size: 11, color: { argb: 'FF61728A' } }; s.alignment = { vertical: 'top' };
