    const trozos = []; SEC.forEach((s, si) => { for (let i = 0; i < s.grupos.length; i += PORT_LOTE) trozos.push({ si: si, orden: [].concat.apply([], s.grupos.slice(i, i + PORT_LOTE)), nCat: s.n }); });
