      const bytes = await doc.save(), nombre = (/^Portafolio/.test(lista.titulo) ? '' : 'Portafolio ') + String(lista.titulo).slice(0, 60) + ' ' + hoyISO();
      const local = URL.createObjectURL(new Blob([bytes], { type: 'application/pdf' }));
